fn delta_pressure_sustains_generations_and_preserves_all_values_after_reopen() {
    let fixture = Fixture::new();
    let config = DatabaseConfig {
        automatic_checkpoint_max_age: Duration::from_secs(3600),
        storage_residency_mode: hawdb_storage::config::StorageResidencyMode::OutOfCore,
        max_out_of_core_delta_bytes: Some(16 * 1024),
        ..DatabaseConfig::default()
    };
    let mut db = Database::open_with_config(&fixture.0, config).unwrap();
    // Establish the initial canonical base before the sustained workload.
    db.checkpoint().unwrap();
    for id in 0..320 {
        db.query_with_params(
            "CREATE (:Memory {id: $id, body: $body})",
            &std::collections::BTreeMap::from([
                ("id".into(), crate::Value::Int(id)),
                ("body".into(), crate::Value::String("b".repeat(512))),
            ]),
        )
        .unwrap();
    }
    let report = db.automatic_checkpoint_report().unwrap().unwrap();
    assert!(
        report.completed_checkpoints >= 2,
        "delta pressure must rotate generations: {report:?}"
    );
    let expected = db
        .query("MATCH (n:Memory) RETURN n.id AS id, n.body AS body ORDER BY id")
        .unwrap()
        .rows;
    assert_eq!(expected.len(), 320);
    for (id, row) in expected.iter().enumerate() {
        assert_eq!(row.get("id"), Some(&crate::Value::Int(id as i64)));
        assert_eq!(
            row.get("body"),
            Some(&crate::Value::String("b".repeat(512)))
        );
    }
    drop(db);
    let mut reopened = Database::open(&fixture.0).unwrap();
    assert_eq!(
        reopened
            .query("MATCH (n:Memory) RETURN n.id AS id, n.body AS body ORDER BY id")
            .unwrap()
            .rows,
        expected
    );
}

fn pending_idle_owner_blocks_pressure_growth_before_admission() {
    let fixture = Fixture::new();
    let (mut db, suspension, next) = seeded(&fixture);
    let control = db.runtime.checkpoint_control_for_test();
    let (probe, paused, resume) = pause();
    let (waiting, waited) = mpsc::channel();
    {
        let mut state = control.lock().unwrap();
        state.idle_start_probe = Some(probe);
        state.frontend_wait_probe = Some(waiting);
    }
    drop(suspension);
    paused.recv_timeout(Duration::from_secs(15)).unwrap();
    let producer = std::thread::spawn(move || -> Result<Database> {
        for id in next..320 {
            create(&mut db, id)?;
        }
        Ok(db)
    });
    let observed = waited.recv_timeout(Duration::from_secs(1));
    resume.send(()).unwrap();
    let produced = producer.join().unwrap();
    assert_eq!(observed.unwrap(), Phase::Idle);
    assert_values_and_reopen(produced.unwrap(), &fixture);
}

fn pressured_writer_finishes_while_a_real_prepared_prefix_remains_paused() {
    let fixture = Fixture::new();
    let (mut db, suspension, next) = seeded(&fixture);
    let old = db.runtime.get().unwrap().store.snapshot_for_read();
    let control = db.runtime.checkpoint_control_for_test();
    let (sealed, observed) = mpsc::channel();
    let (resume, continuation) = mpsc::channel();
    control.lock().unwrap().prefix_seal_probe = Some(Arc::new(PrefixSealProbe {
        sealed,
        resume: Mutex::new(continuation),
    }));
    drop(suspension);
    observed.recv_timeout(Duration::from_secs(15)).unwrap();
    {
        let state = control.lock().unwrap();
        assert_eq!(state.phase, Phase::Preparing);
        assert!(needs_headroom(&state));
    }
    let (finished, completion) = mpsc::channel();
    let producer = std::thread::spawn(move || {
        let result = create(&mut db, next);
        finished.send((db, result)).unwrap();
    });
    // The owner stays paused for this complete observation. Waiting for its
    // entire preparation phase would fail even though the next write fits.
    let early = completion.recv_timeout(Duration::from_secs(1));
    control.lock().unwrap().prefix_seal_probe = None;
    resume.send(()).unwrap();
    producer.join().unwrap();
    let (mut db, result) = match early {
        Ok(value) => value,
        Err(error) => {
            drop(completion.recv_timeout(Duration::from_secs(15)).unwrap());
            panic!("writer waited for the complete Preparing phase: {error}");
        }
    };
    result.unwrap();
    assert!(
        db.automatic_checkpoint_report()
            .unwrap()
            .unwrap()
            .preparation_backoff_expirations
            > 0
    );
    assert_eq!(old.node_count_for_label(None), next as usize);
    drop(old);
    for id in next + 1..320 {
        create(&mut db, id).unwrap();
    }
    assert_values_and_reopen(db, &fixture);
}

fn retiring_owner_blocks_pressure_growth_until_cleanup_finishes() {
    let fixture = Fixture::new();
    let (mut db, suspension, next) = seeded(&fixture);
    let control = db.runtime.checkpoint_control_for_test();
    let (probe, paused, resume) = pause();
    {
        control.lock().unwrap().retirement_probe = Some(probe);
    }
    drop(suspension);
    wait_for(&db, |report| report.completed_checkpoints == 1);
    // Adopt the selected generation before pausing its off-gate retirement.
    drop(db.runtime.get_mut().unwrap());
    paused.recv_timeout(Duration::from_secs(15)).unwrap();
    let (waiting, waited) = mpsc::channel();
    control.lock().unwrap().frontend_wait_probe = Some(waiting);
    let (at_pressure, pressure_reached) = mpsc::channel();
    let producer = std::thread::spawn(move || -> Result<Database> {
        let mut at_pressure = Some(at_pressure);
        for id in next..320 {
            let state = control.lock()?;
            if state.phase == Phase::Retiring
                && pressure_pending(&state)
                && needs_headroom(&state)
                && let Some(at_pressure) = at_pressure.take()
            {
                at_pressure.send(()).unwrap();
            }
            drop(state);
            create(&mut db, id)?;
        }
        Ok(db)
    });
    // Time the blocked call after preceding acknowledged writes have reached
    // the pressure boundary. Filesystem contention during fixture preparation
    // must not consume the separate one-second blocking observation window.
    let reached = pressure_reached.recv_timeout(Duration::from_secs(15));
    let observed = reached.and_then(|()| waited.recv_timeout(Duration::from_secs(1)));
    resume.send(()).unwrap();
    let produced = producer.join().unwrap();
    assert_eq!(observed.unwrap(), Phase::Retiring);
    assert_values_and_reopen(produced.unwrap(), &fixture);
}
